        </div>
      </div>
    </div>
    <script>
      window.__PATCHPAD_BOOT__ = ${JSON.stringify({ reports, activeReportId })};
    </script>
    <script src="/client.js"></script>
  </body>
</html>`);
});

function escapeHtml(value) {
  return String(value)
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;')
    .replace(/'/g, '&#39;');
}

initializeSchema();
seedIfNeeded();

app.listen(PORT, '0.0.0.0', () => {
  console.log(`PatchPad listening on 0.0.0.0:${PORT}`);
});

