.gutter-content {
  position: relative;
  width: max-content;
  min-width: 100%;
  height: 100%;
}

.line-row,
.gutter-row {
  position: absolute;
  left: 0;
  right: 0;
  height: var(--line-height);
}

.line-row {
  font: var(--editor-font);
  line-height: 24px;
  white-space: pre;
}

.line-number,
.preview-line-number {
  position: absolute;
  left: 0;
  width: calc(var(--gutter-width) - 14px);
  padding-right: 12px;
  text-align: right;
  color: rgba(174, 190, 255, 0.58);
  user-select: none;
}

.line-text {
  position: absolute;
  left: var(--gutter-width);
  right: 0;
  white-space: pre;
  padding-right: 40px;
}

.selection-rect,
.match-rect,
.cursor-rect {
  position: absolute;
  top: 2px;
  bottom: 2px;
  border-radius: 4px;
  pointer-events: none;
}

.selection-rect {
  background: rgba(124, 156, 255, 0.34);
}

.match-rect {
  background: rgba(255, 212, 121, 0.28);
}

.match-rect.current-match {
  background: rgba(124, 156, 255, 0.36);
  box-shadow: 0 0 0 1px rgba(124, 156, 255, 0.55) inset;
}

.cursor-rect {
  width: 2px;
  background: #f5f7ff;
  box-shadow: 0 0 0 1px rgba(124, 156, 255, 0.35);
  animation: caret-blink 1.1s steps(1) infinite;
}

@keyframes caret-blink {
  0%, 50% { opacity: 1; }
  51%, 100% { opacity: 0; }
}

.status-bar {
  justify-content: space-between;
  align-items: center;
  padding-top: 2px;
  min-height: 28px;
}

.message-bar {
  min-height: 1.25rem;
}

.history-panel {
  min-width: 0;
}

.history-list {
  display: grid;
  gap: 12px;
  overflow: auto;
  min-height: 0;
  padding-right: 2px;
}

.history-entry {
  padding: 14px;
  border-radius: 16px;
  border: 1px solid var(--border);
  background: rgba(255, 255, 255, 0.03);
  display: grid;
  gap: 10px;
}

.history-entry strong {
  font-size: 1rem;
}

.history-entry small {
  color: var(--muted);
}

.modal {
  position: fixed;
  inset: 0;
  z-index: 50;
  display: grid;
  place-items: center;
  padding: 24px;
}

.modal[hidden] {
  display: none;
}

.modal-backdrop {
  position: absolute;
  inset: 0;
  background: rgba(4, 7, 14, 0.72);
}

.modal-card {
  position: relative;
  z-index: 1;
  width: min(1120px, 100%);
  max-height: calc(100vh - 48px);
  display: flex;
  flex-direction: column;
  padding: 16px;
  gap: 14px;
}

.modal-header {
  justify-content: space-between;
  align-items: start;
}

.preview-shell {
  height: min(72vh, 760px);
}

.preview-scroll {
  background: rgba(5, 8, 16, 0.82);
}

.preview-line-number {
  color: rgba(174, 190, 255, 0.46);
}

.error-text {
  color: var(--bad);
}

.good-text {
  color: var(--good);
}

.warning-text {
  color: var(--warning);
}

(() => {
  const boot = window.__PATCHPAD_BOOT__ || { reports: [], activeReportId: null };
  const editorScroll = document.getElementById('editorScroll');
  const lineGutter = document.getElementById('lineGutter');
  const historyList = document.getElementById('historyList');
  const documentTitle = document.getElementById('documentTitle');
  const documentMeta = document.getElementById('documentMeta');
  const saveState = document.getElementById('saveState');
  const cursorState = document.getElementById('cursorState');
  const messageBar = document.getElementById('messageBar');
  const findBar = document.getElementById('findBar');
  const findInput = document.getElementById('findInput');
  const replaceInput = document.getElementById('replaceInput');
  const findCount = document.getElementById('findCount');
  const findStatus = document.getElementById('findStatus');
  const findToggleButton = document.getElementById('findToggleButton');
  const findPrevButton = document.getElementById('findPrevButton');
  const findNextButton = document.getElementById('findNextButton');
  const replaceCurrentButton = document.getElementById('replaceCurrentButton');
  const replaceAllButton = document.getElementById('replaceAllButton');
  const saveButton = document.getElementById('saveButton');
  const reloadButton = document.getElementById('reloadButton');
  const discardButton = document.getElementById('discardButton');
  const undoButton = document.getElementById('undoButton');
  const redoButton = document.getElementById('redoButton');
  const previewModal = document.getElementById('previewModal');
  const previewGutter = document.getElementById('previewGutter');
  const previewScroll = document.getElementById('previewScroll');
  const previewMeta = document.getElementById('previewMeta');
  const closePreviewButton = document.getElementById('closePreviewButton');
  const reportList = document.getElementById('report-list');

  const state = {
    reportId: boot.activeReportId,
    document: null,
    reportList: boot.reports,
    content: '',
    savedContent: '',
    baseRevision: 1,
    revisions: [],
    selectionRanges: [{ anchor: 0, head: 0 }],
    undoStack: [],
    redoStack: [],
    typingGroup: null,
    matches: [],
    activeMatchIndex: -1,
    findQuery: '',
    preview: null,
    lines: [''],
    lineStarts: [0],
    rowHeight: 24,
    loading: false,
    conflict: null,
  };

  const measureCanvas = document.createElement('canvas');
  const measureContext = measureCanvas.getContext('2d');
  const segmenterGrapheme = typeof Intl !== 'undefined' && Intl.Segmenter ? new Intl.Segmenter(undefined, { granularity: 'grapheme' }) : null;
  const segmenterWord = typeof Intl !== 'undefined' && Intl.Segmenter ? new Intl.Segmenter(undefined, { granularity: 'word' }) : null;
  const metricsCache = new Map();

  let renderQueued = false;
  let previewScrollState = { top: 0, left: 0 };
  let dragSelection = null;

  function escapeHtml(value) {
    return String(value)
      .replace(/&/g, '&amp;')
      .replace(/</g, '&lt;')
      .replace(/>/g, '&gt;')
      .replace(/\"/g, '&quot;')
      .replace(/'/g, '&#39;');
  }

  function formatDate(value) {
    return new Intl.DateTimeFormat(undefined, {
      dateStyle: 'medium',
      timeStyle: 'short',
    }).format(new Date(value));
  }

  function cloneRanges(ranges) {
    return ranges.map((range) => ({ anchor: range.anchor, head: range.head }));
  }

  function normalizedRange(range) {
    return range.anchor <= range.head
      ? { start: range.anchor, end: range.head, anchor: range.anchor, head: range.head }
      : { start: range.head, end: range.anchor, anchor: range.anchor, head: range.head };
  }

  function sortRanges(ranges) {
    return ranges.map(normalizedRange).sort((a, b) => a.start - b.start || a.end - b.end);
  }

  function dedupeCollapsed(ranges) {
    const seen = new Set();
    const result = [];
    for (const range of ranges) {
      if (range.start === range.end) {
        const key = String(range.start);
        if (seen.has(key)) {
          continue;
        }
        seen.add(key);
      }
      result.push(range);
    }
    return result;
  }

  function setMessage(text, kind = '') {
    messageBar.textContent = text || '';
    messageBar.className = kind ? `${kind}-text` : '';
  }

  function setStatus(text, kind = '') {
    saveState.textContent = text;
    saveState.className = kind ? `${kind}-text` : '';
  }

  function updateContentModel(content) {
    state.content = content;
    state.lines = content.split('\n');
    if (!state.lines.length) {
      state.lines = [''];
    }
    state.lineStarts = [0];
    for (let index = 0; index < state.lines.length; index += 1) {
      const line = state.lines[index];
      state.lineStarts[index + 1] = state.lineStarts[index] + line.length + (index < state.lines.length - 1 ? 1 : 0);
    }
    metricsCache.clear();
  }

  function getPrimaryRange() {
    return normalizedRange(state.selectionRanges[0]);
  }

  function setSelections(ranges, options = {}) {
    state.selectionRanges = dedupeCollapsed(sortRanges(ranges));
    if (state.selectionRanges.length === 0) {
      state.selectionRanges = [{ anchor: 0, head: 0 }];
    }
    if (!options.preserveTyping) {
      state.typingGroup = null;
    }
    queueRender();
  }

  function snapshot() {
    return {
      content: state.content,
      selectionRanges: cloneRanges(state.selectionRanges),
      findQuery: state.findQuery,
      activeMatchIndex: state.activeMatchIndex,
      matches: state.matches.slice(),
    };
  }

  function restoreSnapshot(data) {
    updateContentModel(data.content);
    state.selectionRanges = cloneRanges(data.selectionRanges);
    state.findQuery = data.findQuery;
    state.matches = data.matches.slice();
    state.activeMatchIndex = data.activeMatchIndex;
    renderFindBar();
    queueRender();
  }

  function pushUndo(snapshotData, kind) {
    const group = state.typingGroup;
    const now = Date.now();
    const canMerge = group && group.kind === kind && now - group.time < 900;
    if (!canMerge) {
      state.undoStack.push(snapshotData);
      state.redoStack.length = 0;
      state.typingGroup = { kind, time: now };
      return;
    }
    group.time = now;
  }

  function finishGroup() {
    state.typingGroup = null;
  }

  function ensureLineMetrics(line) {
    const cached = metricsCache.get(line);
    if (cached) {
      return cached;
    }
    measureContext.font = getComputedStyle(editorScroll).font;
    const offsets = [0];
    const widths = [0];
    let offset = 0;
    let width = 0;
    const segments = segmenterGrapheme ? Array.from(segmenterGrapheme.segment(line), (part) => part.segment) : Array.from(line);
    for (const segment of segments) {
      offset += segment.length;
      const display = segment === '\t' ? '    ' : segment;
      width += measureContext.measureText(display).width;
      offsets.push(offset);
      widths.push(width);
    }
    const metrics = { offsets, widths, width };
    metricsCache.set(line, metrics);
    return metrics;
  }

  function offsetToX(line, offset) {
    const metrics = ensureLineMetrics(line);
    let low = 0;
    let high = metrics.offsets.length - 1;
    while (low <= high) {
      const mid = (low + high) >> 1;
      if (metrics.offsets[mid] === offset) {
        return metrics.widths[mid];
      }
      if (metrics.offsets[mid] < offset) {
        low = mid + 1;
      } else {
        high = mid - 1;
      }
    }
    return metrics.widths[Math.max(0, high)];
  }

  function xToOffset(line, x) {
    const metrics = ensureLineMetrics(line);
    let low = 0;
    let high = metrics.widths.length - 1;
    while (low <= high) {
      const mid = (low + high) >> 1;
      if (metrics.widths[mid] === x) {
        return metrics.offsets[mid];
      }
      if (metrics.widths[mid] < x) {
        low = mid + 1;
      } else {
        high = mid - 1;
      }
    }
    return metrics.offsets[Math.max(0, high)];
  }

  function lineInfoForOffset(offset) {
    offset = Math.max(0, Math.min(state.content.length, offset));
    let lineIndex = 0;
    for (let index = state.lineStarts.length - 1; index >= 0; index -= 1) {
      if (state.lineStarts[index] <= offset) {
        lineIndex = Math.min(index, state.lines.length - 1);
        break;
      }
    }
    return {
      lineIndex,
      lineStart: state.lineStarts[lineIndex],
      line: state.lines[lineIndex] || '',
      columnOffset: offset - state.lineStarts[lineIndex],
    };
  }

  function nextGrapheme(line, offset, direction) {
    if (direction > 0) {
      if (offset >= line.length) {
        return line.length;
      }
      const rest = line.slice(offset);
      const segments = segmenterGrapheme ? Array.from(segmenterGrapheme.segment(rest), (part) => part.segment) : Array.from(rest);
      return offset + (segments[0]?.length || 1);
    }
    if (offset <= 0) {
      return 0;
    }
    const part = line.slice(0, offset);
    const segments = segmenterGrapheme ? Array.from(segmenterGrapheme.segment(part), (seg) => seg.segment) : Array.from(part);
    return offset - (segments[segments.length - 1]?.length || 1);
  }

  function nextWordBoundary(line, offset, direction) {
    if (!segmenterWord) {
      return nextGrapheme(line, offset, direction);
    }
    const segments = Array.from(segmenterWord.segment(line));
    if (direction > 0) {
      for (const segment of segments) {
        const end = segment.index + segment.segment.length;
        if (segment.index > offset) {
          return segment.index;
        }
        if (segment.index <= offset && offset < end) {
          return end;
        }
      }
      return line.length;
    }
    for (let index = segments.length - 1; index >= 0; index -= 1) {
      const segment = segments[index];
      if (segment.isWordLike && segment.index < offset) {
        return segment.index;
      }
    }
    return 0;
  }

  function selectAll() {
    state.selectionRanges = [{ anchor: 0, head: state.content.length }];
    finishGroup();
    queueRender();
    scrollSelectionIntoView();
  }

  function applyReplacement(ranges, replacement, kind) {
    const sorted = sortRanges(ranges);
    if (!sorted.length) {
      return;
    }
    const before = snapshot();
    pushUndo(before, kind);
    let content = state.content;
    const nextSelections = [];
    for (let index = sorted.length - 1; index >= 0; index -= 1) {
      const range = sorted[index];
      content = content.slice(0, range.start) + replacement + content.slice(range.end);
      nextSelections.unshift({ anchor: range.start + replacement.length, head: range.start + replacement.length });
    }
    updateContentModel(content);
    state.selectionRanges = nextSelections;
    state.matches = [];
    state.activeMatchIndex = -1;
    renderFindBar();
    queueRender();
  }

  function typeText(text) {
    applyReplacement(sortRanges(state.selectionRanges), text, 'insert');
  }

  function deleteByDirection(direction) {
    const ranges = sortRanges(state.selectionRanges).map((range) => {
      if (range.start !== range.end) {
        return range;
      }
      const info = lineInfoForOffset(range.start);
      const relative = range.start - info.lineStart;
      const line = info.line;
      const nextRelative = direction < 0 ? nextGrapheme(line, relative, -1) : nextGrapheme(line, relative, 1);
      return direction < 0
        ? { start: info.lineStart + nextRelative, end: range.start, anchor: range.start, head: range.start }
        : { start: range.start, end: info.lineStart + nextRelative, anchor: range.start, head: range.start };
    });
    applyReplacement(ranges, '', direction < 0 ? 'backspace' : 'delete');
  }

  function moveRanges(direction, { shift = false, byWord = false } = {}) {
    state.selectionRanges = state.selectionRanges.map((range) => {
      const normalized = normalizedRange(range);
      const collapseTarget = shift ? range.head : (direction > 0 ? normalized.end : normalized.start);
      const info = lineInfoForOffset(collapseTarget);
      const relative = collapseTarget - info.lineStart;
      const nextRelative = byWord ? nextWordBoundary(info.line, relative, direction) : nextGrapheme(info.line, relative, direction);
      const nextOffset = info.lineStart + nextRelative;
      return shift ? { anchor: range.anchor, head: nextOffset } : { anchor: nextOffset, head: nextOffset };
    });
    state.selectionRanges = dedupeCollapsed(sortRanges(state.selectionRanges));
    finishGroup();
    queueRender();
    scrollSelectionIntoView();
  }

  function moveVertical(direction, shift = false) {
    state.selectionRanges = state.selectionRanges.map((range) => {
      const current = shift ? range.head : normalizedRange(range).end;
      const info = lineInfoForOffset(current);
      const nextLine = Math.max(0, Math.min(state.lines.length - 1, info.lineIndex + direction));
      const line = state.lines[nextLine] || '';
      const nextColumn = Array.from(segmenterGrapheme ? segmenterGrapheme.segment(info.line.slice(0, info.columnOffset)) : info.line.slice(0, info.columnOffset)).length;
      const nextMetrics = ensureLineMetrics(line);
      const nextRelative = nextMetrics.offsets[Math.min(nextColumn, nextMetrics.offsets.length - 1)];
      const nextOffset = state.lineStarts[nextLine] + nextRelative;
      return shift ? { anchor: range.anchor, head: nextOffset } : { anchor: nextOffset, head: nextOffset };
    });
    state.selectionRanges = dedupeCollapsed(sortRanges(state.selectionRanges));
    finishGroup();
    queueRender();
    scrollSelectionIntoView();
  }

  function currentSelectionText() {
    const range = getPrimaryRange();
    return state.content.slice(range.start, range.end);
  }

  function indentSelection(outdent = false) {
    const range = getPrimaryRange();
    const startLine = lineInfoForOffset(range.start).lineIndex;
    const endLine = lineInfoForOffset(range.end).lineIndex;
    const lines = state.lines.slice(startLine, endLine + 1);
    if (!lines.length) {
      return;
    }
    const before = snapshot();
    pushUndo(before, outdent ? 'outdent' : 'indent');
    const adjusted = lines.map((line) => {
      if (outdent) {
        if (line.startsWith('\t')) {
          return line.slice(1);
        }
        if (line.startsWith('    ')) {
          return line.slice(4);
        }
        if (line.startsWith(' ')) {
          return line.replace(/^ +/, (match) => match.slice(Math.min(4, match.length)));
        }
        return line;
      }
      return `\t${line}`;
    });
    const startOffset = state.lineStarts[startLine];
    const endOffset = endLine < state.lines.length - 1 ? state.lineStarts[endLine + 1] : state.content.length;
    updateContentModel(state.content.slice(0, startOffset) + adjusted.join('\n') + state.content.slice(endOffset));
    state.selectionRanges = [{ anchor: startOffset, head: startOffset + adjusted.join('\n').length }];
    queueRender();
    setDirtyStatus();
  }

  function openPreview(revisionNumber) {
    fetch(`/api/reports/${encodeURIComponent(state.document.id)}/revisions/${encodeURIComponent(revisionNumber)}`)
      .then((response) => response.json().then((data) => ({ response, data })))
      .then(({ response, data }) => {
        if (!response.ok) {
          throw new Error(data.error || 'Unable to preview revision.');
        }
        state.preview = data;
        previewMeta.textContent = `Revision ${data.revisionNumber} • ${formatDate(data.createdAt)}`;
        previewModal.hidden = false;
        previewScroll.scrollTop = 0;
        previewScroll.scrollLeft = 0;
        renderPreview();
      })
      .catch((error) => setMessage(error.message, 'error'));
  }

  function restoreRevision(revisionNumber) {
    fetch(`/api/reports/${encodeURIComponent(state.document.id)}/revisions/${encodeURIComponent(revisionNumber)}`)
      .then((response) => response.json().then((data) => ({ response, data })))
      .then(({ response, data }) => {
        if (!response.ok) {
          throw new Error(data.error || 'Unable to restore revision.');
        }
        const before = snapshot();
        pushUndo(before, 'restore');
        updateContentModel(data.content);
        state.selectionRanges = [{ anchor: 0, head: 0 }];
        state.matches = [];
        state.activeMatchIndex = -1;
        renderFindBar();
        queueRender();
        setDirtyStatus();
        setMessage(`Restored revision ${data.revisionNumber} into the editor. Save to keep it.`, 'warning');
      })
      .catch((error) => setMessage(error.message, 'error'));
  }

  function renderReports() {
    Array.from(reportList.querySelectorAll('.report-chip')).forEach((chip) => {
      chip.classList.toggle('active', chip.dataset.reportId === state.reportId);
      chip.onclick = () => loadReport(chip.dataset.reportId);
    });
  }

  function renderHeader() {
    if (!state.document) {
      documentTitle.textContent = 'Loading…';
      documentMeta.textContent = '';
      return;
    }
    documentTitle.textContent = state.document.title;
    documentMeta.textContent = `Author: ${state.document.author} • ${state.document.summary}`;
  }

  function renderHistory() {
    if (!state.revisions.length) {
      historyList.innerHTML = '<div class="history-entry">No revisions available.</div>';
      return;
    }
    historyList.innerHTML = state.revisions.map((revision) => `
      <article class="history-entry">
        <div>
          <strong>Revision ${revision.revisionNumber}</strong>
          <div><small>${formatDate(revision.createdAt)}</small></div>
        </div>
        <div class="history-entry-actions">
          <button type="button" data-preview-revision="${revision.revisionNumber}">Preview</button>
          <button type="button" data-restore-revision="${revision.revisionNumber}">Restore</button>
        </div>
      </article>
    `).join('');
    historyList.querySelectorAll('[data-preview-revision]').forEach((button) => {
      button.onclick = () => openPreview(button.dataset.previewRevision);
    });
    historyList.querySelectorAll('[data-restore-revision]').forEach((button) => {
      button.onclick = () => restoreRevision(button.dataset.restoreRevision);
    });
  }

  function renderFindBar() {
    findCount.textContent = `${state.matches.length} match${state.matches.length === 1 ? '' : 'es'}`;
    if (!state.findQuery) {
      findStatus.textContent = 'Search the open report.';
    } else if (!state.matches.length) {
      findStatus.textContent = 'No matches.';
    } else {
      findStatus.textContent = `Match ${state.activeMatchIndex + 1} of ${state.matches.length}`;
    }
  }

  function setDirtyStatus() {
    if (state.conflict) {
      setStatus(`Save conflict: server is at revision ${state.conflict.currentRevision}.`, 'warning');
      return;
    }
    if (state.content === state.savedContent) {
      setStatus(`Saved at revision ${state.baseRevision}.`, 'good');
    } else {
      setStatus(`Unsaved changes • base revision ${state.baseRevision}`, 'warning');
    }
  }

  function renderStatus() {
    setDirtyStatus();
    const info = lineInfoForOffset(getPrimaryRange().head);
    const column = Array.from(segmenterGrapheme ? segmenterGrapheme.segment(info.line.slice(0, info.columnOffset)) : info.line.slice(0, info.columnOffset)).length;
    cursorState.textContent = state.selectionRanges.length > 1
      ? `Line ${info.lineIndex + 1}, Column ${column + 1} • ${state.selectionRanges.length} carets`
      : `Line ${info.lineIndex + 1}, Column ${column + 1}`;
  }

  function renderEditorSurface(scrollContainer, gutterContainer, content, mode) {
    const rowHeight = state.rowHeight;
    const scrollTop = mode === 'preview' ? previewScrollState.top : scrollContainer.scrollTop;
    const scrollLeft = mode === 'preview' ? previewScrollState.left : scrollContainer.scrollLeft;
    const visibleHeight = scrollContainer.clientHeight || 0;
    const startLine = Math.max(0, Math.floor(scrollTop / rowHeight) - 2);
    const endLine = Math.min(content.lines.length - 1, Math.ceil((scrollTop + visibleHeight) / rowHeight) + 2);
    const totalHeight = content.lines.length * rowHeight;
    const ranges = content.selectionRanges || [];
    const matches = content.matches || [];
    const activeMatchIndex = content.activeMatchIndex ?? -1;

    const rows = [];
    const gutterRows = [];
    let maxWidth = 0;
    for (let lineIndex = startLine; lineIndex <= endLine; lineIndex += 1) {
      const line = content.lines[lineIndex] || '';
      const lineStart = content.lineStarts[lineIndex] || 0;
      const lineWidth = ensureLineMetrics(line).width;
      maxWidth = Math.max(maxWidth, lineWidth);
      const top = lineIndex * rowHeight;
      const selectionRects = [];
      const matchRects = [];
      const carets = [];

      for (const range of ranges) {
        const start = Math.max(range.start, lineStart);
        const end = Math.min(range.end, lineStart + line.length);
        if (start < end) {
          const left = offsetToX(line, start - lineStart);
          selectionRects.push({ left, width: Math.max(1, offsetToX(line, end - lineStart) - left) });
        }
        if (range.start === range.end && range.start >= lineStart && range.start <= lineStart + line.length) {
          carets.push({ left: offsetToX(line, range.start - lineStart) });
        }
      }

      for (let index = 0; index < matches.length; index += 1) {
        const match = matches[index];
        const start = Math.max(match.start, lineStart);
        const end = Math.min(match.end, lineStart + line.length);
        if (start < end) {
          const left = offsetToX(line, start - lineStart);
          matchRects.push({ left, width: Math.max(1, offsetToX(line, end - lineStart) - left), current: index === activeMatchIndex });
        }
      }

      rows.push(`
        <div class="line-row" style="top:${top}px; height:${rowHeight}px;">
          ${matchRects.map((rect) => `<div class="match-rect${rect.current ? ' current-match' : ''}" style="left:${rect.left}px; width:${rect.width}px;"></div>`).join('')}
          ${selectionRects.map((rect) => `<div class="selection-rect" style="left:${rect.left}px; width:${rect.width}px;"></div>`).join('')}
          ${carets.map((rect) => `<div class="cursor-rect" style="left:${rect.left}px;"></div>`).join('')}
          <span class="line-text">${escapeHtml(line)}</span>
        </div>
      `);
      gutterRows.push(`<div class="gutter-row" style="top:${top}px; height:${rowHeight}px;"><span class="line-number">${lineIndex + 1}</span></div>`);
    }

    scrollContainer.innerHTML = `<div class="editor-content" style="height:${totalHeight}px; min-width:${maxWidth + 200}px;">${rows.join('')}</div>`;
    gutterContainer.innerHTML = `<div class="gutter-content" style="height:${totalHeight}px;">${gutterRows.join('')}</div>`;
    scrollContainer.scrollTop = scrollTop;
    scrollContainer.scrollLeft = scrollLeft;
  }

  function renderEditor() {
    if (!state.document) {
      return;
    }
    renderEditorSurface(editorScroll, lineGutter, {
      lines: state.lines,
      lineStarts: state.lineStarts,
      selectionRanges: state.selectionRanges,
      matches: state.matches,
      activeMatchIndex: state.activeMatchIndex,
    }, 'editor');
    renderStatus();
  }

  function renderPreview() {
    if (!state.preview) {
      return;
    }
    const lines = state.preview.content.split('\n');
    const lineStarts = [0];
    for (let index = 0; index < lines.length; index += 1) {
      lineStarts[index + 1] = lineStarts[index] + lines[index].length + (index < lines.length - 1 ? 1 : 0);
    }
    renderEditorSurface(previewScroll, previewGutter, {
      lines,
      lineStarts,
      selectionRanges: [],
      matches: [],
      activeMatchIndex: -1,
    }, 'preview');
  }

  function queueRender() {
    if (renderQueued) {
      return;
    }
    renderQueued = true;
    requestAnimationFrame(() => {
      renderQueued = false;
      renderEditor();
      if (state.preview) {
        renderPreview();
      }
    });
  }

  function scrollSelectionIntoView() {
    const info = lineInfoForOffset(getPrimaryRange().head);
    const caretX = offsetToX(info.line, info.columnOffset);
    const caretY = info.lineIndex * state.rowHeight;
    if (caretY < editorScroll.scrollTop + 16) {
      editorScroll.scrollTop = Math.max(0, caretY - state.rowHeight * 3);
    } else if (caretY + state.rowHeight > editorScroll.scrollTop + editorScroll.clientHeight - 16) {
      editorScroll.scrollTop = Math.max(0, caretY - editorScroll.clientHeight + state.rowHeight * 4);
    }
    if (caretX < editorScroll.scrollLeft + 24) {
      editorScroll.scrollLeft = Math.max(0, caretX - 40);
    } else if (caretX > editorScroll.scrollLeft + editorScroll.clientWidth - 24) {
      editorScroll.scrollLeft = Math.max(0, caretX - editorScroll.clientWidth + 80);
    }
  }

  function handleEditorMouseDown(event) {
    const rect = editorScroll.getBoundingClientRect();
    const x = editorScroll.scrollLeft + event.clientX - rect.left;
    const y = editorScroll.scrollTop + event.clientY - rect.top;
    const lineIndex = Math.max(0, Math.min(state.lines.length - 1, Math.floor(y / state.rowHeight)));
    const line = state.lines[lineIndex] || '';
    const offset = state.lineStarts[lineIndex] + xToOffset(line, Math.max(0, x));

    if (event.altKey || event.ctrlKey || event.metaKey) {
      state.selectionRanges = [...state.selectionRanges, { anchor: offset, head: offset }];
      finishGroup();
      queueRender();
      return;
    }

    if (event.detail >= 3) {
      state.selectionRanges = [{ anchor: state.lineStarts[lineIndex], head: state.lineStarts[lineIndex] + line.length }];
    } else if (event.detail === 2 && segmenterWord) {
      const relative = offset - state.lineStarts[lineIndex];
      const segments = Array.from(segmenterWord.segment(line));
      let selected = { start: 0, end: line.length };
      for (const segment of segments) {
        const end = segment.index + segment.segment.length;
        if (segment.isWordLike && segment.index <= relative && relative <= end) {
          selected = { start: segment.index, end };
          break;
        }
      }
      state.selectionRanges = [{ anchor: state.lineStarts[lineIndex] + selected.start, head: state.lineStarts[lineIndex] + selected.end }];
    } else {
      state.selectionRanges = [{ anchor: offset, head: offset }];
      dragSelection = { start: offset, active: true };
    }
    finishGroup();
    queueRender();
    scrollSelectionIntoView();
  }

  function handleEditorMouseMove(event) {
    if (!dragSelection || !dragSelection.active) {
      return;
    }
    const rect = editorScroll.getBoundingClientRect();
    const x = editorScroll.scrollLeft + event.clientX - rect.left;
    const y = editorScroll.scrollTop + event.clientY - rect.top;
    const lineIndex = Math.max(0, Math.min(state.lines.length - 1, Math.floor(y / state.rowHeight)));
    const line = state.lines[lineIndex] || '';
    const offset = state.lineStarts[lineIndex] + xToOffset(line, Math.max(0, x));
    state.selectionRanges = [{ anchor: dragSelection.start, head: offset }];
    queueRender();
    scrollSelectionIntoView();
  }

  function finishDragging() {
    dragSelection = null;
  }

  function handleEditorShortcut(event) {
    const isMac = navigator.platform.toLowerCase().includes('mac');
    const mod = isMac ? event.metaKey : event.ctrlKey;
    const key = event.key.toLowerCase();

    if (mod && key === 'f') {
      event.preventDefault();
      openFindBar();
      return true;
    }
    if (mod && key === 's') {
      event.preventDefault();
      saveReport();
      return true;
    }
    if (mod && key === 'z' && !event.shiftKey) {
      event.preventDefault();
      handleUndo();
      return true;
    }
    if (mod && (key === 'y' || (key === 'z' && event.shiftKey))) {
      event.preventDefault();
      handleRedo();
      return true;
    }
    if (mod && key === 'a') {
      event.preventDefault();
      selectAll();
      return true;
    }
    return false;
  }

  function handleEditorKeyDown(event) {
    if (handleEditorShortcut(event)) {
      return;
    }

    const mod = event.ctrlKey || event.metaKey;
    const shift = event.shiftKey;
    const key = event.key;

    if (key === 'Escape') {
      event.preventDefault();
      findInput.focus();
      return;
    }
    if (key === 'Tab') {
      event.preventDefault();
      insertTab(shift);
      return;
    }
    if (key === 'Enter') {
      event.preventDefault();
      typeText('\n');
      return;
    }
    if (key === 'Backspace') {
      event.preventDefault();
      deleteByDirection(-1);
      return;
    }
    if (key === 'Delete') {
      event.preventDefault();
      deleteByDirection(1);
      return;
    }
    if (key === 'ArrowLeft') {
      event.preventDefault();
      moveRanges(-1, { shift, byWord: mod });
      return;
    }
    if (key === 'ArrowRight') {
      event.preventDefault();
      moveRanges(1, { shift, byWord: mod });
      return;
    }
    if (key === 'ArrowUp') {
      event.preventDefault();
      moveVertical(-1, shift);
      return;
    }
    if (key === 'ArrowDown') {
      event.preventDefault();
      moveVertical(1, shift);
      return;
    }
    if (key === 'Home') {
      event.preventDefault();
      state.selectionRanges = state.selectionRanges.map((range) => {
        const info = lineInfoForOffset(range.head);
        const target = mod ? 0 : info.lineStart;
        return shift ? { anchor: range.anchor, head: target } : { anchor: target, head: target };
      });
      state.selectionRanges = dedupeCollapsed(sortRanges(state.selectionRanges));
      finishGroup();
      queueRender();
      scrollSelectionIntoView();
      return;
    }
    if (key === 'End') {
      event.preventDefault();
      state.selectionRanges = state.selectionRanges.map((range) => {
        const info = lineInfoForOffset(range.head);
        const target = mod ? state.content.length : info.lineStart + info.line.length;
        return shift ? { anchor: range.anchor, head: target } : { anchor: target, head: target };
      });
      state.selectionRanges = dedupeCollapsed(sortRanges(state.selectionRanges));
      finishGroup();
      queueRender();
      scrollSelectionIntoView();
      return;
    }
    if (mod && key === 'g') {
      event.preventDefault();
      navigateMatches(shift ? -1 : 1);
      return;
    }
    if (key.length === 1 && !mod) {
      event.preventDefault();
      typeText(key);
    }
  }

  function handlePaste(event) {
    event.preventDefault();
    typeText(event.clipboardData?.getData('text/plain') || '');
  }

  function handleCopy(event) {
    const range = getPrimaryRange();
    if (range.start === range.end) {
      return;
    }
    event.preventDefault();
    event.clipboardData?.setData('text/plain', state.content.slice(range.start, range.end));
  }

  function handleCut(event) {
    const range = getPrimaryRange();
    if (range.start === range.end) {
      return;
    }
    event.preventDefault();
    event.clipboardData?.setData('text/plain', state.content.slice(range.start, range.end));
    applyReplacement([range], '', 'cut');
  }

  function handleFindInputKeyDown(event) {
    if (event.key === 'Escape') {
      event.preventDefault();
      editorScroll.focus();
      return;
    }
    if (event.key === 'Enter') {
      event.preventDefault();
      navigateMatches(event.shiftKey ? -1 : 1);
    }
  }

  function handleScroll() {
    queueRender();
  }

  function handlePreviewScroll() {
    previewScrollState = { top: previewScroll.scrollTop, left: previewScroll.scrollLeft };
    queueRender();
  }

  function handleWindowResize() {
    metricsCache.clear();
    queueRender();
  }

  function bindUi() {
    editorScroll.addEventListener('keydown', handleEditorKeyDown);
    editorScroll.addEventListener('paste', handlePaste);
    editorScroll.addEventListener('copy', handleCopy);
    editorScroll.addEventListener('cut', handleCut);
    editorScroll.addEventListener('mousedown', handleEditorMouseDown);
    editorScroll.addEventListener('mousemove', handleEditorMouseMove);
    window.addEventListener('mouseup', finishDragging);
    editorScroll.addEventListener('scroll', handleScroll);
    previewScroll.addEventListener('scroll', handlePreviewScroll);
    findInput.addEventListener('input', () => {
      state.findQuery = findInput.value;
      state.activeMatchIndex = 0;
      findMatches();
    });
    findInput.addEventListener('keydown', handleFindInputKeyDown);
    replaceInput.addEventListener('keydown', (event) => {
      if (event.key === 'Escape') {
        editorScroll.focus();
      }
    });
    findToggleButton.addEventListener('click', () => {
      findBar.hidden = !findBar.hidden;
      if (!findBar.hidden) {
        findInput.focus();
        findInput.select();
      } else {
        editorScroll.focus();
      }
    });
    findPrevButton.addEventListener('click', () => navigateMatches(-1));
    findNextButton.addEventListener('click', () => navigateMatches(1));
    replaceCurrentButton.addEventListener('click', replaceCurrentMatch);
    replaceAllButton.addEventListener('click', replaceAllMatches);
    saveButton.addEventListener('click', saveReport);
    reloadButton.addEventListener('click', reloadLatest);
    discardButton.addEventListener('click', reloadLatest);
    undoButton.addEventListener('click', handleUndo);
    redoButton.addEventListener('click', handleRedo);
    closePreviewButton.addEventListener('click', closePreview);
    previewModal.addEventListener('click', (event) => {
      if (event.target === previewModal || event.target.classList.contains('modal-backdrop')) {
        closePreview();
      }
    });
    window.addEventListener('resize', handleWindowResize);
  }

  function closePreview() {
    state.preview = null;
    previewModal.hidden = true;
    editorScroll.focus();
  }

  function reloadLatest() {
    if (state.document) {
      loadReport(state.document.id);
    }
  }

  function handleUndo() {
    if (!state.undoStack.length) {
      setMessage('Nothing to undo.', 'warning');
      return;
    }
    const current = snapshot();
    const previous = state.undoStack.pop();
    state.redoStack.push(current);
    restoreSnapshot(previous);
    setDirtyStatus();
    setMessage('Undid the last change.', 'good');
  }

  function handleRedo() {
    if (!state.redoStack.length) {
      setMessage('Nothing to redo.', 'warning');
      return;
    }
    const current = snapshot();
    const next = state.redoStack.pop();
    state.undoStack.push(current);
    restoreSnapshot(next);
    setDirtyStatus();
    setMessage('Redid the last change.', 'good');
  }

  function insertTab(shiftKey) {
    const range = getPrimaryRange();
    if (range.start !== range.end && state.content.slice(range.start, range.end).includes('\n')) {
      indentSelection(shiftKey);
      return;
    }
    if (shiftKey) {
      indentSelection(true);
      return;
    }
    typeText('\t');
  }

  function openFindBar() {
    findBar.hidden = false;
    findInput.focus();
    findInput.select();
  }

  function loadReport(reportId) {
    if (!reportId) {
      return Promise.resolve();
    }
    setStatus('Loading report…');
    setMessage('');
    return fetch(`/api/reports/${encodeURIComponent(reportId)}`)
      .then((response) => response.json().then((data) => ({ response, data })))
      .then(({ response, data }) => {
        if (!response.ok) {
          throw new Error(data.error || 'Failed to load report.');
        }
        state.reportId = data.document.id;
        state.document = data.document;
        state.revisions = data.revisions;
        state.baseRevision = data.document.currentRevision;
        state.savedContent = data.document.content;
        state.conflict = null;
        state.undoStack = [];
        state.redoStack = [];
        state.typingGroup = null;
        state.findQuery = '';
        findInput.value = '';
        state.matches = [];
        state.activeMatchIndex = -1;
        updateContentModel(data.document.content);
        state.selectionRanges = [{ anchor: 0, head: 0 }];
        renderHeader();
        renderReports();
        renderHistory();
        renderFindBar();
        setDirtyStatus();
        queueRender();
        setMessage('Report loaded.', 'good');
      })
      .catch((error) => setMessage(error.message, 'error'));
  }

  function openPreview(revisionNumber) {
    fetch(`/api/reports/${encodeURIComponent(state.document.id)}/revisions/${encodeURIComponent(revisionNumber)}`)
      .then((response) => response.json().then((data) => ({ response, data })))
      .then(({ response, data }) => {
        if (!response.ok) {
          throw new Error(data.error || 'Unable to preview revision.');
        }
        state.preview = data;
        previewMeta.textContent = `Revision ${data.revisionNumber} • ${formatDate(data.createdAt)}`;
        previewModal.hidden = false;
        previewScroll.scrollTop = 0;
        previewScroll.scrollLeft = 0;
        renderPreview();
      })
      .catch((error) => setMessage(error.message, 'error'));
  }

  function restoreRevision(revisionNumber) {
    fetch(`/api/reports/${encodeURIComponent(state.document.id)}/revisions/${encodeURIComponent(revisionNumber)}`)
      .then((response) => response.json().then((data) => ({ response, data })))
      .then(({ response, data }) => {
        if (!response.ok) {
          throw new Error(data.error || 'Unable to restore revision.');
        }
        const before = snapshot();
        pushUndo(before, 'restore');
        updateContentModel(data.content);
        state.selectionRanges = [{ anchor: 0, head: 0 }];
        state.matches = [];
        state.activeMatchIndex = -1;
        renderFindBar();
        queueRender();
        setDirtyStatus();
        setMessage(`Restored revision ${data.revisionNumber} into the editor. Save to keep it.`, 'warning');
      })
      .catch((error) => setMessage(error.message, 'error'));
  }

  function renderReports() {
    Array.from(reportList.querySelectorAll('.report-chip')).forEach((chip) => {
      chip.classList.toggle('active', chip.dataset.reportId === state.reportId);
      chip.onclick = () => loadReport(chip.dataset.reportId);
    });
  }

  function renderHeader() {
    if (!state.document) {
      documentTitle.textContent = 'Loading…';
      documentMeta.textContent = '';
      return;
    }
    documentTitle.textContent = state.document.title;
    documentMeta.textContent = `Author: ${state.document.author} • ${state.document.summary}`;
  }

  function renderHistory() {
    if (!state.revisions.length) {
      historyList.innerHTML = '<div class="history-entry">No revisions available.</div>';
      return;
    }
    historyList.innerHTML = state.revisions.map((revision) => `
      <article class="history-entry">
        <div>
          <strong>Revision ${revision.revisionNumber}</strong>
          <div><small>${formatDate(revision.createdAt)}</small></div>
        </div>
        <div class="history-entry-actions">
          <button type="button" data-preview-revision="${revision.revisionNumber}">Preview</button>
          <button type="button" data-restore-revision="${revision.revisionNumber}">Restore</button>
        </div>
      </article>
    `).join('');
    historyList.querySelectorAll('[data-preview-revision]').forEach((button) => {
      button.onclick = () => openPreview(button.dataset.previewRevision);
    });
    historyList.querySelectorAll('[data-restore-revision]').forEach((button) => {
      button.onclick = () => restoreRevision(button.dataset.restoreRevision);
    });
  }

  function renderFindBar() {
    findCount.textContent = `${state.matches.length} match${state.matches.length === 1 ? '' : 'es'}`;
    if (!state.findQuery) {
      findStatus.textContent = 'Search the open report.';
    } else if (!state.matches.length) {
      findStatus.textContent = 'No matches.';
    } else {
      findStatus.textContent = `Match ${state.activeMatchIndex + 1} of ${state.matches.length}`;
    }
  }

  function setDirtyStatus() {
    if (state.conflict) {
      setStatus(`Save conflict: server is at revision ${state.conflict.currentRevision}.`, 'warning');
      return;
    }
    if (state.content === state.savedContent) {
      setStatus(`Saved at revision ${state.baseRevision}.`, 'good');
    } else {
      setStatus(`Unsaved changes • base revision ${state.baseRevision}`, 'warning');
    }
  }

  function renderStatus() {
    setDirtyStatus();
    const info = lineInfoForOffset(getPrimaryRange().head);
    const column = Array.from(segmenterGrapheme ? segmenterGrapheme.segment(info.line.slice(0, info.columnOffset)) : info.line.slice(0, info.columnOffset)).length;
    cursorState.textContent = state.selectionRanges.length > 1
      ? `Line ${info.lineIndex + 1}, Column ${column + 1} • ${state.selectionRanges.length} carets`
      : `Line ${info.lineIndex + 1}, Column ${column + 1}`;
  }

  function renderEditorSurface(scrollContainer, gutterContainer, content, mode) {
    const rowHeight = state.rowHeight;
    const scrollTop = mode === 'preview' ? previewScrollState.top : scrollContainer.scrollTop;
    const scrollLeft = mode === 'preview' ? previewScrollState.left : scrollContainer.scrollLeft;
    const visibleHeight = scrollContainer.clientHeight || 0;
    const startLine = Math.max(0, Math.floor(scrollTop / rowHeight) - 2);
    const endLine = Math.min(content.lines.length - 1, Math.ceil((scrollTop + visibleHeight) / rowHeight) + 2);
    const totalHeight = content.lines.length * rowHeight;
    const ranges = content.selectionRanges || [];
    const matches = content.matches || [];
    const activeMatchIndex = content.activeMatchIndex ?? -1;

    const rows = [];
    const gutterRows = [];
    let maxWidth = 0;
    for (let lineIndex = startLine; lineIndex <= endLine; lineIndex += 1) {
      const line = content.lines[lineIndex] || '';
      const lineStart = content.lineStarts[lineIndex] || 0;
      const lineWidth = ensureLineMetrics(line).width;
      maxWidth = Math.max(maxWidth, lineWidth);
      const top = lineIndex * rowHeight;
      const selectionRects = [];
      const matchRects = [];
      const carets = [];

      for (const range of ranges) {
        const start = Math.max(range.start, lineStart);
        const end = Math.min(range.end, lineStart + line.length);
        if (start < end) {
          const left = offsetToX(line, start - lineStart);
          selectionRects.push({ left, width: Math.max(1, offsetToX(line, end - lineStart) - left) });
        }
        if (range.start === range.end && range.start >= lineStart && range.start <= lineStart + line.length) {
          carets.push({ left: offsetToX(line, range.start - lineStart) });
        }
      }

      for (let index = 0; index < matches.length; index += 1) {
        const match = matches[index];
        const start = Math.max(match.start, lineStart);
        const end = Math.min(match.end, lineStart + line.length);
        if (start < end) {
          const left = offsetToX(line, start - lineStart);
          matchRects.push({ left, width: Math.max(1, offsetToX(line, end - lineStart) - left), current: index === activeMatchIndex });
        }
      }

      rows.push(`
        <div class="line-row" style="top:${top}px; height:${rowHeight}px;">
          ${matchRects.map((rect) => `<div class="match-rect${rect.current ? ' current-match' : ''}" style="left:${rect.left}px; width:${rect.width}px;"></div>`).join('')}
          ${selectionRects.map((rect) => `<div class="selection-rect" style="left:${rect.left}px; width:${rect.width}px;"></div>`).join('')}
          ${carets.map((rect) => `<div class="cursor-rect" style="left:${rect.left}px;"></div>`).join('')}
          <span class="line-text">${escapeHtml(line)}</span>
        </div>
      `);
      gutterRows.push(`<div class="gutter-row" style="top:${top}px; height:${rowHeight}px;"><span class="line-number">${lineIndex + 1}</span></div>`);
    }

    scrollContainer.innerHTML = `<div class="editor-content" style="height:${totalHeight}px; min-width:${maxWidth + 200}px;">${rows.join('')}</div>`;
    gutterContainer.innerHTML = `<div class="gutter-content" style="height:${totalHeight}px;">${gutterRows.join('')}</div>`;
    scrollContainer.scrollTop = scrollTop;
    scrollContainer.scrollLeft = scrollLeft;
  }

  function renderEditor() {
    if (!state.document) {
      return;
    }
    renderEditorSurface(editorScroll, lineGutter, {
      lines: state.lines,
      lineStarts: state.lineStarts,
      selectionRanges: state.selectionRanges,
      matches: state.matches,
      activeMatchIndex: state.activeMatchIndex,
    }, 'editor');
    renderStatus();
  }

  function renderPreview() {
    if (!state.preview) {
      return;
    }
    const lines = state.preview.content.split('\n');
    const lineStarts = [0];
    for (let index = 0; index < lines.length; index += 1) {
      lineStarts[index + 1] = lineStarts[index] + lines[index].length + (index < lines.length - 1 ? 1 : 0);
    }
    renderEditorSurface(previewScroll, previewGutter, {
      lines,
      lineStarts,
      selectionRanges: [],
      matches: [],
      activeMatchIndex: -1,
    }, 'preview');
  }

  function queueRender() {
    if (renderQueued) {
      return;
    }
    renderQueued = true;
    requestAnimationFrame(() => {
      renderQueued = false;
      renderEditor();
      if (state.preview) {
        renderPreview();
      }
    });
  }

  function scrollSelectionIntoView() {
    const info = lineInfoForOffset(getPrimaryRange().head);
    const caretX = offsetToX(info.line, info.columnOffset);
    const caretY = info.lineIndex * state.rowHeight;
    if (caretY < editorScroll.scrollTop + 16) {
      editorScroll.scrollTop = Math.max(0, caretY - state.rowHeight * 3);
    } else if (caretY + state.rowHeight > editorScroll.scrollTop + editorScroll.clientHeight - 16) {
      editorScroll.scrollTop = Math.max(0, caretY - editorScroll.clientHeight + state.rowHeight * 4);
    }
    if (caretX < editorScroll.scrollLeft + 24) {
      editorScroll.scrollLeft = Math.max(0, caretX - 40);
    } else if (caretX > editorScroll.scrollLeft + editorScroll.clientWidth - 24) {
      editorScroll.scrollLeft = Math.max(0, caretX - editorScroll.clientWidth + 80);
    }
  }

  function handleEditorMouseDown(event) {
    const rect = editorScroll.getBoundingClientRect();
    const x = editorScroll.scrollLeft + event.clientX - rect.left;
    const y = editorScroll.scrollTop + event.clientY - rect.top;
    const lineIndex = Math.max(0, Math.min(state.lines.length - 1, Math.floor(y / state.rowHeight)));
    const line = state.lines[lineIndex] || '';
    const offset = state.lineStarts[lineIndex] + xToOffset(line, Math.max(0, x));

    if (event.altKey || event.ctrlKey || event.metaKey) {
      state.selectionRanges = [...state.selectionRanges, { anchor: offset, head: offset }];
      finishGroup();
      queueRender();
      return;
    }

    if (event.detail >= 3) {
      state.selectionRanges = [{ anchor: state.lineStarts[lineIndex], head: state.lineStarts[lineIndex] + line.length }];
    } else if (event.detail === 2 && segmenterWord) {
      const relative = offset - state.lineStarts[lineIndex];
      const segments = Array.from(segmenterWord.segment(line));
      let selected = { start: 0, end: line.length };
      for (const segment of segments) {
        const end = segment.index + segment.segment.length;
        if (segment.isWordLike && segment.index <= relative && relative <= end) {
          selected = { start: segment.index, end };
          break;
        }
      }
      state.selectionRanges = [{ anchor: state.lineStarts[lineIndex] + selected.start, head: state.lineStarts[lineIndex] + selected.end }];
    } else {
      state.selectionRanges = [{ anchor: offset, head: offset }];
      dragSelection = { start: offset, active: true };
    }
    finishGroup();
    queueRender();
    scrollSelectionIntoView();
  }

  function handleEditorMouseMove(event) {
    if (!dragSelection || !dragSelection.active) {
      return;
    }
    const rect = editorScroll.getBoundingClientRect();
    const x = editorScroll.scrollLeft + event.clientX - rect.left;
    const y = editorScroll.scrollTop + event.clientY - rect.top;
    const lineIndex = Math.max(0, Math.min(state.lines.length - 1, Math.floor(y / state.rowHeight)));
    const line = state.lines[lineIndex] || '';
    const offset = state.lineStarts[lineIndex] + xToOffset(line, Math.max(0, x));
    state.selectionRanges = [{ anchor: dragSelection.start, head: offset }];
    queueRender();
    scrollSelectionIntoView();
  }

  function finishDragging() {
    dragSelection = null;
  }

  function handleEditorShortcut(event) {
    const isMac = navigator.platform.toLowerCase().includes('mac');
    const mod = isMac ? event.metaKey : event.ctrlKey;
    const key = event.key.toLowerCase();

    if (mod && key === 'f') {
      event.preventDefault();
      openFindBar();
      return true;
    }
    if (mod && key === 's') {
      event.preventDefault();
      saveReport();
      return true;
    }
    if (mod && key === 'z' && !event.shiftKey) {
      event.preventDefault();
      handleUndo();
      return true;
    }
    if (mod && (key === 'y' || (key === 'z' && event.shiftKey))) {
      event.preventDefault();
      handleRedo();
      return true;
    }
    if (mod && key === 'a') {
      event.preventDefault();
      selectAll();
      return true;
    }
    return false;
  }

  function handleEditorKeyDown(event) {
    if (handleEditorShortcut(event)) {
      return;
    }

    const mod = event.ctrlKey || event.metaKey;
    const shift = event.shiftKey;
    const key = event.key;

    if (key === 'Escape') {
      event.preventDefault();
      findInput.focus();
      return;
    }
    if (key === 'Tab') {
      event.preventDefault();
      insertTab(shift);
      return;
    }
    if (key === 'Enter') {
      event.preventDefault();
      typeText('\n');
      return;
    }
    if (key === 'Backspace') {
      event.preventDefault();
      deleteByDirection(-1);
      return;
    }
    if (key === 'Delete') {
      event.preventDefault();
      deleteByDirection(1);
      return;
    }
    if (key === 'ArrowLeft') {
      event.preventDefault();
      moveRanges(-1, { shift, byWord: mod });
      return;
    }
    if (key === 'ArrowRight') {
      event.preventDefault();
      moveRanges(1, { shift, byWord: mod });
      return;
    }
    if (key === 'ArrowUp') {
      event.preventDefault();
      moveVertical(-1, shift);
      return;
    }
    if (key === 'ArrowDown') {
      event.preventDefault();
      moveVertical(1, shift);
      return;
    }
    if (key === 'Home') {
      event.preventDefault();
      state.selectionRanges = state.selectionRanges.map((range) => {
        const info = lineInfoForOffset(range.head);
        const target = mod ? 0 : info.lineStart;
        return shift ? { anchor: range.anchor, head: target } : { anchor: target, head: target };
      });
      state.selectionRanges = dedupeCollapsed(sortRanges(state.selectionRanges));
      finishGroup();
      queueRender();
      scrollSelectionIntoView();
      return;
    }
    if (key === 'End') {
      event.preventDefault();
      state.selectionRanges = state.selectionRanges.map((range) => {
        const info = lineInfoForOffset(range.head);
        const target = mod ? state.content.length : info.lineStart + info.line.length;
        return shift ? { anchor: range.anchor, head: target } : { anchor: target, head: target };
      });
      state.selectionRanges = dedupeCollapsed(sortRanges(state.selectionRanges));
      finishGroup();
      queueRender();
      scrollSelectionIntoView();
      return;
    }
    if (mod && key === 'g') {
      event.preventDefault();
      navigateMatches(shift ? -1 : 1);
      return;
    }
    if (key.length === 1 && !mod) {
      event.preventDefault();
      typeText(key);
    }
  }

  function handlePaste(event) {
    event.preventDefault();
    typeText(event.clipboardData?.getData('text/plain') || '');
  }

  function handleCopy(event) {
    const range = getPrimaryRange();
    if (range.start === range.end) {
      return;
    }
    event.preventDefault();
    event.clipboardData?.setData('text/plain', state.content.slice(range.start, range.end));
  }

  function handleCut(event) {
    const range = getPrimaryRange();
    if (range.start === range.end) {
      return;
    }
    event.preventDefault();
    event.clipboardData?.setData('text/plain', state.content.slice(range.start, range.end));
    applyReplacement([range], '', 'cut');
  }

  function handleFindInputKeyDown(event) {
    if (event.key === 'Escape') {
      event.preventDefault();
      editorScroll.focus();
      return;
    }
    if (event.key === 'Enter') {
      event.preventDefault();
      navigateMatches(event.shiftKey ? -1 : 1);
    }
  }

  function handleScroll() {
    queueRender();
  }

  function handlePreviewScroll() {
    previewScrollState = { top: previewScroll.scrollTop, left: previewScroll.scrollLeft };
    queueRender();
  }

  function handleWindowResize() {
    metricsCache.clear();
    queueRender();
  }

  function bindUi() {
    editorScroll.addEventListener('keydown', handleEditorKeyDown);
    editorScroll.addEventListener('paste', handlePaste);
    editorScroll.addEventListener('copy', handleCopy);
    editorScroll.addEventListener('cut', handleCut);
    editorScroll.addEventListener('mousedown', handleEditorMouseDown);
    editorScroll.addEventListener('mousemove', handleEditorMouseMove);
    window.addEventListener('mouseup', finishDragging);
    editorScroll.addEventListener('scroll', handleScroll);
    previewScroll.addEventListener('scroll', handlePreviewScroll);
    findInput.addEventListener('input', () => {
      state.findQuery = findInput.value;
      state.activeMatchIndex = 0;
      findMatches();
    });
    findInput.addEventListener('keydown', handleFindInputKeyDown);
    replaceInput.addEventListener('keydown', (event) => {
      if (event.key === 'Escape') {
        editorScroll.focus();
      }
    });
    findToggleButton.addEventListener('click', () => {
      findBar.hidden = !findBar.hidden;
      if (!findBar.hidden) {
        findInput.focus();
        findInput.select();
      } else {
        editorScroll.focus();
      }
    });
    findPrevButton.addEventListener('click', () => navigateMatches(-1));
    findNextButton.addEventListener('click', () => navigateMatches(1));
    replaceCurrentButton.addEventListener('click', replaceCurrentMatch);
    replaceAllButton.addEventListener('click', replaceAllMatches);
    saveButton.addEventListener('click', saveReport);
    reloadButton.addEventListener('click', reloadLatest);
    discardButton.addEventListener('click', reloadLatest);
    undoButton.addEventListener('click', handleUndo);
    redoButton.addEventListener('click', handleRedo);
    closePreviewButton.addEventListener('click', closePreview);
    previewModal.addEventListener('click', (event) => {
      if (event.target === previewModal || event.target.classList.contains('modal-backdrop')) {
        closePreview();
      }
    });
    window.addEventListener('resize', handleWindowResize);
  }

  function closePreview() {
    state.preview = null;
    previewModal.hidden = true;
    editorScroll.focus();
  }

  function reloadLatest() {
    if (state.document) {
      loadReport(state.document.id);
    }
  }

  function handleUndo() {
    if (!state.undoStack.length) {
      setMessage('Nothing to undo.', 'warning');
      return;
    }
    const current = snapshot();
    const previous = state.undoStack.pop();
    state.redoStack.push(current);
    restoreSnapshot(previous);
    setDirtyStatus();
    setMessage('Undid the last change.', 'good');
  }

  function handleRedo() {
    if (!state.redoStack.length) {
      setMessage('Nothing to redo.', 'warning');
      return;
    }
    const current = snapshot();
    const next = state.redoStack.pop();
    state.undoStack.push(current);
    restoreSnapshot(next);
    setDirtyStatus();
    setMessage('Redid the last change.', 'good');
  }

  function insertTab(shiftKey) {
    const range = getPrimaryRange();
    if (range.start !== range.end && state.content.slice(range.start, range.end).includes('\n')) {
      indentSelection(shiftKey);
      return;
    }
    if (shiftKey) {
      indentSelection(true);
      return;
    }
    typeText('\t');
  }

  function openFindBar() {
    findBar.hidden = false;
    findInput.focus();
    findInput.select();
  }

  function loadReport(reportId) {
    if (!reportId) {
      return Promise.resolve();
    }
    setStatus('Loading report…');
    setMessage('');
    return fetch(`/api/reports/${encodeURIComponent(reportId)}`)
      .then((response) => response.json().then((data) => ({ response, data })))
      .then(({ response, data }) => {
        if (!response.ok) {
          throw new Error(data.error || 'Failed to load report.');
        }
        state.reportId = data.document.id;
        state.document = data.document;
        state.revisions = data.revisions;
        state.baseRevision = data.document.currentRevision;
        state.savedContent = data.document.content;
        state.conflict = null;
        state.undoStack = [];
        state.redoStack = [];
        state.typingGroup = null;
        state.findQuery = '';
        findInput.value = '';
        state.matches = [];
        state.activeMatchIndex = -1;
        updateContentModel(data.document.content);
        state.selectionRanges = [{ anchor: 0, head: 0 }];
        renderHeader();
        renderReports();
        renderHistory();
        renderFindBar();
        setDirtyStatus();
        queueRender();
        setMessage('Report loaded.', 'good');
      })
      .catch((error) => setMessage(error.message, 'error'));
  }

  function openPreview(revisionNumber) {
    fetch(`/api/reports/${encodeURIComponent(state.document.id)}/revisions/${encodeURIComponent(revisionNumber)}`)
      .then((response) => response.json().then((data) => ({ response, data })))
      .then(({ response, data }) => {
        if (!response.ok) {
          throw new Error(data.error || 'Unable to preview revision.');
        }
        state.preview = data;
        previewMeta.textContent = `Revision ${data.revisionNumber} • ${formatDate(data.createdAt)}`;
        previewModal.hidden = false;
        previewScroll.scrollTop = 0;
        previewScroll.scrollLeft = 0;
        renderPreview();
      })
      .catch((error) => setMessage(error.message, 'error'));
  }

  function restoreRevision(revisionNumber) {
    fetch(`/api/reports/${encodeURIComponent(state.document.id)}/revisions/${encodeURIComponent(revisionNumber)}`)
      .then((response) => response.json().then((data) => ({ response, data })))
      .then(({ response, data }) => {
        if (!response.ok) {
          throw new Error(data.error || 'Unable to restore revision.');
        }
        const before = snapshot();
        pushUndo(before, 'restore');
        updateContentModel(data.content);
        state.selectionRanges = [{ anchor: 0, head: 0 }];
        state.matches = [];
        state.activeMatchIndex = -1;
        renderFindBar();
        queueRender();
        setDirtyStatus();
        setMessage(`Restored revision ${data.revisionNumber} into the editor. Save to keep it.`, 'warning');
      })
      .catch((error) => setMessage(error.message, 'error'));
  }

  function renderReports() {
    Array.from(reportList.querySelectorAll('.report-chip')).forEach((chip) => {
      chip.classList.toggle('active', chip.dataset.reportId === state.reportId);
      chip.onclick = () => loadReport(chip.dataset.reportId);
    });
  }

  function renderHeader() {
    if (!state.document) {
      documentTitle.textContent = 'Loading…';
      documentMeta.textContent = '';
      return;
    }
    documentTitle.textContent = state.document.title;
    documentMeta.textContent = `Author: ${state.document.author} • ${state.document.summary}`;
  }

  function renderHistory() {
    if (!state.revisions.length) {
      historyList.innerHTML = '<div class="history-entry">No revisions available.</div>';
      return;
    }
    historyList.innerHTML = state.revisions.map((revision) => `
      <article class="history-entry">
        <div>
          <strong>Revision ${revision.revisionNumber}</strong>
          <div><small>${formatDate(revision.createdAt)}</small></div>
        </div>
        <div class="history-entry-actions">
          <button type="button" data-preview-revision="${revision.revisionNumber}">Preview</button>
          <button type="button" data-restore-revision="${revision.revisionNumber}">Restore</button>
        </div>
      </article>
    `).join('');
    historyList.querySelectorAll('[data-preview-revision]').forEach((button) => {
      button.onclick = () => openPreview(button.dataset.previewRevision);
    });
    historyList.querySelectorAll('[data-restore-revision]').forEach((button) => {
      button.onclick = () => restoreRevision(button.dataset.restoreRevision);
    });
  }

  function renderFindBar() {
    findCount.textContent = `${state.matches.length} match${state.matches.length === 1 ? '' : 'es'}`;
    if (!state.findQuery) {
      findStatus.textContent = 'Search the open report.';
    } else if (!state.matches.length) {
      findStatus.textContent = 'No matches.';
    } else {
      findStatus.textContent = `Match ${state.activeMatchIndex + 1} of ${state.matches.length}`;
    }
  }

  function setDirtyStatus() {
    if (state.conflict) {
      setStatus(`Save conflict: server is at revision ${state.conflict.currentRevision}.`, 'warning');
      return;
    }
    if (state.content === state.savedContent) {
      setStatus(`Saved at revision ${state.baseRevision}.`, 'good');
    } else {
      setStatus(`Unsaved changes • base revision ${state.baseRevision}`, 'warning');
    }
  }

  function renderStatus() {
    setDirtyStatus();
    const info = lineInfoForOffset(getPrimaryRange().head);
    const column = Array.from(segmenterGrapheme ? segmenterGrapheme.segment(info.line.slice(0, info.columnOffset)) : info.line.slice(0, info.columnOffset)).length;
    cursorState.textContent = state.selectionRanges.length > 1
      ? `Line ${info.lineIndex + 1}, Column ${column + 1} • ${state.selectionRanges.length} carets`
      : `Line ${info.lineIndex + 1}, Column ${column + 1}`;
  }

  function renderEditorSurface(scrollContainer, gutterContainer, content, mode) {
    const rowHeight = state.rowHeight;
    const scrollTop = mode === 'preview' ? previewScrollState.top : scrollContainer.scrollTop;
    const scrollLeft = mode === 'preview' ? previewScrollState.left : scrollContainer.scrollLeft;
    const visibleHeight = scrollContainer.clientHeight || 0;
    const startLine = Math.max(0, Math.floor(scrollTop / rowHeight) - 2);
    const endLine = Math.min(content.lines.length - 1, Math.ceil((scrollTop + visibleHeight) / rowHeight) + 2);
    const totalHeight = content.lines.length * rowHeight;
    const ranges = content.selectionRanges || [];
    const matches = content.matches || [];
    const activeMatchIndex = content.activeMatchIndex ?? -1;

    const rows = [];
    const gutterRows = [];
    let maxWidth = 0;
    for (let lineIndex = startLine; lineIndex <= endLine; lineIndex += 1) {
      const line = content.lines[lineIndex] || '';
      const lineStart = content.lineStarts[lineIndex] || 0;
      const lineWidth = ensureLineMetrics(line).width;
      maxWidth = Math.max(maxWidth, lineWidth);
      const top = lineIndex * rowHeight;
      const selectionRects = [];
      const matchRects = [];
      const carets = [];

      for (const range of ranges) {
        const start = Math.max(range.start, lineStart);
        const end = Math.min(range.end, lineStart + line.length);
        if (start < end) {
          const left = offsetToX(line, start - lineStart);
          selectionRects.push({ left, width: Math.max(1, offsetToX(line, end - lineStart) - left) });
        }
        if (range.start === range.end && range.start >= lineStart && range.start <= lineStart + line.length) {
          carets.push({ left: offsetToX(line, range.start - lineStart) });
        }
      }

      for (let index = 0; index < matches.length; index += 1) {
        const match = matches[index];
        const start = Math.max(match.start, lineStart);
        const end = Math.min(match.end, lineStart + line.length);
        if (start < end) {
          const left = offsetToX(line, start - lineStart);
          matchRects.push({ left, width: Math.max(1, offsetToX(line, end - lineStart) - left), current: index === activeMatchIndex });
        }
      }

      rows.push(`
        <div class="line-row" style="top:${top}px; height:${rowHeight}px;">
          ${matchRects.map((rect) => `<div class="match-rect${rect.current ? ' current-match' : ''}" style="left:${rect.left}px; width:${rect.width}px;"></div>`).join('')}
          ${selectionRects.map((rect) => `<div class="selection-rect" style="left:${rect.left}px; width:${rect.width}px;"></div>`).join('')}
          ${carets.map((rect) => `<div class="cursor-rect" style="left:${rect.left}px;"></div>`).join('')}
          <span class="line-text">${escapeHtml(line)}</span>
        </div>
      `);
      gutterRows.push(`<div class="gutter-row" style="top:${top}px; height:${rowHeight}px;"><span class="line-number">${lineIndex + 1}</span></div>`);
    }

    scrollContainer.innerHTML = `<div class="editor-content" style="height:${totalHeight}px; min-width:${maxWidth + 200}px;">${rows.join('')}</div>`;
    gutterContainer.innerHTML = `<div class="gutter-content" style="height:${totalHeight}px;">${gutterRows.join('')}</div>`;
    scrollContainer.scrollTop = scrollTop;
    scrollContainer.scrollLeft = scrollLeft;
  }

  function renderEditor() {
    if (!state.document) {
      return;
    }
    renderEditorSurface(editorScroll, lineGutter, {
      lines: state.lines,
      lineStarts: state.lineStarts,
      selectionRanges: state.selectionRanges,
      matches: state.matches,
      activeMatchIndex: state.activeMatchIndex,
    }, 'editor');
    renderStatus();
  }

  function renderPreview() {
    if (!state.preview) {
      return;
    }
    const lines = state.preview.content.split('\n');
    const lineStarts = [0];
    for (let index = 0; index < lines.length; index += 1) {
      lineStarts[index + 1] = lineStarts[index] + lines[index].length + (index < lines.length - 1 ? 1 : 0);
    }
    renderEditorSurface(previewScroll, previewGutter, {
      lines,
      lineStarts,
      selectionRanges: [],
      matches: [],
      activeMatchIndex: -1,
    }, 'preview');
  }

  function queueRender() {
    if (renderQueued) {
      return;
    }
    renderQueued = true;
    requestAnimationFrame(() => {
      renderQueued = false;
      renderEditor();
      if (state.preview) {
        renderPreview();
      }
    });
  }

  function scrollSelectionIntoView() {
    const info = lineInfoForOffset(getPrimaryRange().head);
    const caretX = offsetToX(info.line, info.columnOffset);
    const caretY = info.lineIndex * state.rowHeight;
    if (caretY < editorScroll.scrollTop + 16) {
      editorScroll.scrollTop = Math.max(0, caretY - state.rowHeight * 3);
    } else if (caretY + state.rowHeight > editorScroll.scrollTop + editorScroll.clientHeight - 16) {
      editorScroll.scrollTop = Math.max(0, caretY - editorScroll.clientHeight + state.rowHeight * 4);
    }
    if (caretX < editorScroll.scrollLeft + 24) {
      editorScroll.scrollLeft = Math.max(0, caretX - 40);
    } else if (caretX > editorScroll.scrollLeft + editorScroll.clientWidth - 24) {
      editorScroll.scrollLeft = Math.max(0, caretX - editorScroll.clientWidth + 80);
    }
  }

  function handleEditorMouseDown(event) {
    const rect = editorScroll.getBoundingClientRect();
    const x = editorScroll.scrollLeft + event.clientX - rect.left;
    const y = editorScroll.scrollTop + event.clientY - rect.top;
    const lineIndex = Math.max(0, Math.min(state.lines.length - 1, Math.floor(y / state.rowHeight)));
    const line = state.lines[lineIndex] || '';
    const offset = state.lineStarts[lineIndex] + xToOffset(line, Math.max(0, x));

    if (event.altKey || event.ctrlKey || event.metaKey) {
      state.selectionRanges = [...state.selectionRanges, { anchor: offset, head: offset }];
      finishGroup();
      queueRender();
      return;
    }

    if (event.detail >= 3) {
      state.selectionRanges = [{ anchor: state.lineStarts[lineIndex], head: state.lineStarts[lineIndex] + line.length }];
    } else if (event.detail === 2 && segmenterWord) {
      const relative = offset - state.lineStarts[lineIndex];
      const segments = Array.from(segmenterWord.segment(line));
      let selected = { start: 0, end: line.length };
      for (const segment of segments) {
        const end = segment.index + segment.segment.length;
        if (segment.isWordLike && segment.index <= relative && relative <= end) {
          selected = { start: segment.index, end };
          break;
        }
      }
      state.selectionRanges = [{ anchor: state.lineStarts[lineIndex] + selected.start, head: state.lineStarts[lineIndex] + selected.end }];
    } else {
      state.selectionRanges = [{ anchor: offset, head: offset }];
      dragSelection = { start: offset, active: true };
    }
    finishGroup();
    queueRender();
    scrollSelectionIntoView();
  }

  function handleEditorMouseMove(event) {
    if (!dragSelection || !dragSelection.active) {
      return;
    }
    const rect = editorScroll.getBoundingClientRect();
    const x = editorScroll.scrollLeft + event.clientX - rect.left;
    const y = editorScroll.scrollTop + event.clientY - rect.top;
    const lineIndex = Math.max(0, Math.min(state.lines.length - 1, Math.floor(y / state.rowHeight)));
    const line = state.lines[lineIndex] || '';
    const offset = state.lineStarts[lineIndex] + xToOffset(line, Math.max(0, x));
    state.selectionRanges = [{ anchor: dragSelection.start, head: offset }];
    queueRender();
    scrollSelectionIntoView();
  }

  function finishDragging() {
    dragSelection = null;
  }

  function handleEditorShortcut(event) {
    const isMac = navigator.platform.toLowerCase().includes('mac');
    const mod = isMac ? event.metaKey : event.ctrlKey;
    const key = event.key.toLowerCase();

    if (mod && key === 'f') {
      event.preventDefault();
      openFindBar();
      return true;
    }
    if (mod && key === 's') {
      event.preventDefault();
      saveReport();
      return true;
    }
    if (mod && key === 'z' && !event.shiftKey) {
      event.preventDefault();
      handleUndo();
      return true;
    }
    if (mod && (key === 'y' || (key === 'z' && event.shiftKey))) {
      event.preventDefault();
      handleRedo();
      return true;
    }
    if (mod && key === 'a') {
      event.preventDefault();
      selectAll();
      return true;
    }
    return false;
  }

  function handleEditorKeyDown(event) {
    if (handleEditorShortcut(event)) {
      return;
    }

    const mod = event.ctrlKey || event.metaKey;
    const shift = event.shiftKey;
    const key = event.key;

    if (key === 'Escape') {
      event.preventDefault();
      findInput.focus();
      return;
    }
    if (key === 'Tab') {
      event.preventDefault();
      insertTab(shift);
      return;
    }
    if (key === 'Enter') {
      event.preventDefault();
      typeText('\n');
      return;
    }
    if (key === 'Backspace') {
      event.preventDefault();
      deleteByDirection(-1);
      return;
    }
    if (key === 'Delete') {
      event.preventDefault();
      deleteByDirection(1);
      return;
    }
    if (key === 'ArrowLeft') {
      event.preventDefault();
      moveRanges(-1, { shift, byWord: mod });
      return;
    }
    if (key === 'ArrowRight') {
      event.preventDefault();
      moveRanges(1, { shift, byWord: mod });
      return;
    }
    if (key === 'ArrowUp') {
      event.preventDefault();
      moveVertical(-1, shift);
      return;
    }
    if (key === 'ArrowDown') {
      event.preventDefault();
      moveVertical(1, shift);
      return;
    }
    if (key === 'Home') {
      event.preventDefault();
      state.selectionRanges = state.selectionRanges.map((range) => {
        const info = lineInfoForOffset(range.head);
        const target = mod ? 0 : info.lineStart;
        return shift ? { anchor: range.anchor, head: target } : { anchor: target, head: target };
      });
      state.selectionRanges = dedupeCollapsed(sortRanges(state.selectionRanges));
      finishGroup();
      queueRender();
      scrollSelectionIntoView();
      return;
    }
    if (key === 'End') {
      event.preventDefault();
      state.selectionRanges = state.selectionRanges.map((range) => {
        const info = lineInfoForOffset(range.head);
        const target = mod ? state.content.length : info.lineStart + info.line.length;
        return shift ? { anchor: range.anchor, head: target } : { anchor: target, head: target };
      });
      state.selectionRanges = dedupeCollapsed(sortRanges(state.selectionRanges));
      finishGroup();
      queueRender();
      scrollSelectionIntoView();
      return;
    }
    if (mod && key === 'g') {
      event.preventDefault();
      navigateMatches(shift ? -1 : 1);
      return;
    }
    if (key.length === 1 && !mod) {
      event.preventDefault();
      typeText(key);
    }
  }

  function handlePaste(event) {
    event.preventDefault();
    typeText(event.clipboardData?.getData('text/plain') || '');
  }

  function handleCopy(event) {
    const range = getPrimaryRange();
    if (range.start === range.end) {
      return;
    }
    event.preventDefault();
    event.clipboardData?.setData('text/plain', state.content.slice(range.start, range.end));
  }

  function handleCut(event) {
    const range = getPrimaryRange();
    if (range.start === range.end) {
      return;
    }
    event.preventDefault();
    event.clipboardData?.setData('text/plain', state.content.slice(range.start, range.end));
    applyReplacement([range], '', 'cut');
  }

  function handleFindInputKeyDown(event) {
    if (event.key === 'Escape') {
      event.preventDefault();
      editorScroll.focus();
      return;
    }
    if (event.key === 'Enter') {
      event.preventDefault();
      navigateMatches(event.shiftKey ? -1 : 1);
    }
  }

  function handleScroll() {
    queueRender();
  }

  function handlePreviewScroll() {
    previewScrollState = { top: previewScroll.scrollTop, left: previewScroll.scrollLeft };
    queueRender();
  }

  function handleWindowResize() {
    metricsCache.clear();
    queueRender();
  }

  function bindUi() {
    editorScroll.addEventListener('keydown', handleEditorKeyDown);
    editorScroll.addEventListener('paste', handlePaste);
    editorScroll.addEventListener('copy', handleCopy);
    editorScroll.addEventListener('cut', handleCut);
    editorScroll.addEventListener('mousedown', handleEditorMouseDown);
    editorScroll.addEventListener('mousemove', handleEditorMouseMove);
    window.addEventListener('mouseup', finishDragging);
    editorScroll.addEventListener('scroll', handleScroll);
    previewScroll.addEventListener('scroll', handlePreviewScroll);
    findInput.addEventListener('input', () => {
      state.findQuery = findInput.value;
      state.activeMatchIndex = 0;
      findMatches();
    });
    findInput.addEventListener('keydown', handleFindInputKeyDown);
    replaceInput.addEventListener('keydown', (event) => {
      if (event.key === 'Escape') {
        editorScroll.focus();
      }
    });
    findToggleButton.addEventListener('click', () => {
      findBar.hidden = !findBar.hidden;
      if (!findBar.hidden) {
        findInput.focus();
        findInput.select();
      } else {
        editorScroll.focus();
      }
    });
    findPrevButton.addEventListener('click', () => navigateMatches(-1));
    findNextButton.addEventListener('click', () => navigateMatches(1));
    replaceCurrentButton.addEventListener('click', replaceCurrentMatch);
    replaceAllButton.addEventListener('click', replaceAllMatches);
    saveButton.addEventListener('click', saveReport);
    reloadButton.addEventListener('click', reloadLatest);
    discardButton.addEventListener('click', reloadLatest);
    undoButton.addEventListener('click', handleUndo);
    redoButton.addEventListener('click', handleRedo);
    closePreviewButton.addEventListener('click', closePreview);
    previewModal.addEventListener('click', (event) => {
      if (event.target === previewModal || event.target.classList.contains('modal-backdrop')) {
        closePreview();
      }
    });
    window.addEventListener('resize', handleWindowResize);
  }

  function closePreview() {
    state.preview = null;
    previewModal.hidden = true;
    editorScroll.focus();
  }

  function reloadLatest() {
    if (state.document) {
      loadReport(state.document.id);
    }
  }

  function handleUndo() {
    if (!state.undoStack.length) {
      setMessage('Nothing to undo.', 'warning');
      return;
    }
    const current = snapshot();
    const previous = state.undoStack.pop();
    state.redoStack.push(current);
    restoreSnapshot(previous);
    setDirtyStatus();
    setMessage('Undid the last change.', 'good');
  }

  function handleRedo() {
    if (!state.redoStack.length) {
      setMessage('Nothing to redo.', 'warning');
      return;
    }
    const current = snapshot();
    const next = state.redoStack.pop();
    state.undoStack.push(current);
    restoreSnapshot(next);
    setDirtyStatus();
    setMessage('Redid the last change.', 'good');
  }

  function insertTab(shiftKey) {
    const range = getPrimaryRange();
    if (range.start !== range.end && state.content.slice(range.start, range.end).includes('\n')) {
      indentSelection(shiftKey);
      return;
    }
    if (shiftKey) {
      indentSelection(true);
      return;
    }
    typeText('\t');
  }

  function openFindBar() {
    findBar.hidden = false;
    findInput.focus();
    findInput.select();
  }

  function loadReport(reportId) {
    if (!reportId) {
      return Promise.resolve();
    }
    setStatus('Loading report…');
    setMessage('');
    return fetch(`/api/reports/${encodeURIComponent(reportId)}`)
      .then((response) => response.json().then((data) => ({ response, data })))
      .then(({ response, data }) => {
        if (!response.ok) {
          throw new Error(data.error || 'Failed to load report.');
        }
        state.reportId = data.document.id;
        state.document = data.document;
        state.revisions = data.revisions;
        state.baseRevision = data.document.currentRevision;
        state.savedContent = data.document.content;
        state.conflict = null;
        state.undoStack = [];
        state.redoStack = [];
        state.typingGroup = null;
        state.findQuery = '';
        findInput.value = '';
        state.matches = [];
        state.activeMatchIndex = -1;
        updateContentModel(data.document.content);
        state.selectionRanges = [{ anchor: 0, head: 0 }];
        renderHeader();
        renderReports();
        renderHistory();
        renderFindBar();
        setDirtyStatus();
        queueRender();
        setMessage('Report loaded.', 'good');
      })
      .catch((error) => setMessage(error.message, 'error'));
  }

  function openPreview(revisionNumber) {
    fetch(`/api/reports/${encodeURIComponent(state.document.id)}/revisions/${encodeURIComponent(revisionNumber)}`)
      .then((response) => response.json().then((data) => ({ response, data })))
      .then(({ response, data }) => {
        if (!response.ok) {
          throw new Error(data.error || 'Unable to preview revision.');
        }
        state.preview = data;
        previewMeta.textContent = `Revision ${data.revisionNumber} • ${formatDate(data.createdAt)}`;
        previewModal.hidden = false;
        previewScroll.scrollTop = 0;
        previewScroll.scrollLeft = 0;
        renderPreview();
      })
      .catch((error) => setMessage(error.message, 'error'));
  }

  function restoreRevision(revisionNumber) {
    fetch(`/api/reports/${encodeURIComponent(state.document.id)}/revisions/${encodeURIComponent(revisionNumber)}`)
      .then((response) => response.json().then((data) => ({ response, data })))
      .then(({ response, data }) => {
        if (!response.ok) {
          throw new Error(data.error || 'Unable to restore revision.');
        }
        const before = snapshot();
        pushUndo(before, 'restore');
        updateContentModel(data.content);
        state.selectionRanges = [{ anchor: 0, head: 0 }];
        state.matches = [];
        state.activeMatchIndex = -1;
        renderFindBar();
        queueRender();
        setDirtyStatus();
        setMessage(`Restored revision ${data.revisionNumber} into the editor. Save to keep it.`, 'warning');
      })
      .catch((error) => setMessage(error.message, 'error'));
  }

  function renderReports() {
    Array.from(reportList.querySelectorAll('.report-chip')).forEach((chip) => {
      chip.classList.toggle('active', chip.dataset.reportId === state.reportId);
      chip.onclick = () => loadReport(chip.dataset.reportId);
    });
  }

  function renderHeader() {
    if (!state.document) {
      documentTitle.textContent = 'Loading…';
      documentMeta.textContent = '';
      return;
    }
    documentTitle.textContent = state.document.title;
    documentMeta.textContent = `Author: ${state.document.author} • ${state.document.summary}`;
  }

  function renderHistory() {
    if (!state.revisions.length) {
      historyList.innerHTML = '<div class="history-entry">No revisions available.</div>';
      return;
    }
    historyList.innerHTML = state.revisions.map((revision) => `
      <article class="history-entry">
        <div>
          <strong>Revision ${revision.revisionNumber}</strong>
          <div><small>${formatDate(revision.createdAt)}</small></div>
        </div>
        <div class="history-entry-actions">
          <button type="button" data-preview-revision="${revision.revisionNumber}">Preview</button>
          <button type="button" data-restore-revision="${revision.revisionNumber}">Restore</button>
        </div>
      </article>
    `).join('');
    historyList.querySelectorAll('[data-preview-revision]').forEach((button) => {
      button.onclick = () => openPreview(button.dataset.previewRevision);
    });
    historyList.querySelectorAll('[data-restore-revision]').forEach((button) => {
      button.onclick = () => restoreRevision(button.dataset.restoreRevision);
    });
  }

  function renderFindBar() {
    findCount.textContent = `${state.matches.length} match${state.matches.length === 1 ? '' : 'es'}`;
    if (!state.findQuery) {
      findStatus.textContent = 'Search the open report.';
    } else if (!state.matches.length) {
      findStatus.textContent = 'No matches.';
    } else {
      findStatus.textContent = `Match ${state.activeMatchIndex + 1} of ${state.matches.length}`;
    }
  }

  function setDirtyStatus() {
    if (state.conflict) {
      setStatus(`Save conflict: server is at revision ${state.conflict.currentRevision}.`, 'warning');
      return;
    }
    if (state.content === state.savedContent) {
      setStatus(`Saved at revision ${state.baseRevision}.`, 'good');
    } else {
      setStatus(`Unsaved changes • base revision ${state.baseRevision}`, 'warning');
    }
  }

  function renderStatus() {
    setDirtyStatus();
    const info = lineInfoForOffset(getPrimaryRange().head);
    const column = Array.from(segmenterGrapheme ? segmenterGrapheme.segment(info.line.slice(0, info.columnOffset)) : info.line.slice(0, info.columnOffset)).length;
    cursorState.textContent = state.selectionRanges.length > 1
      ? `Line ${info.lineIndex + 1}, Column ${column + 1} • ${state.selectionRanges.length} carets`
      : `Line ${info.lineIndex + 1}, Column ${column + 1}`;
  }

  function renderEditorSurface(scrollContainer, gutterContainer, content, mode) {
    const rowHeight = state.rowHeight;
    const scrollTop = mode === 'preview' ? previewScrollState.top : scrollContainer.scrollTop;
    const scrollLeft = mode === 'preview' ? previewScrollState.left : scrollContainer.scrollLeft;
    const visibleHeight = scrollContainer.clientHeight || 0;
    const startLine = Math.max(0, Math.floor(scrollTop / rowHeight) - 2);
    const endLine = Math.min(content.lines.length - 1, Math.ceil((scrollTop + visibleHeight) / rowHeight) + 2);
    const totalHeight = content.lines.length * rowHeight;
    const ranges = content.selectionRanges || [];
    const matches = content.matches || [];
    const activeMatchIndex = content.activeMatchIndex ?? -1;

    const rows = [];
    const gutterRows = [];
    let maxWidth = 0;
    for (let lineIndex = startLine; lineIndex <= endLine; lineIndex += 1) {
      const line = content.lines[lineIndex] || '';
      const lineStart = content.lineStarts[lineIndex] || 0;
      const lineWidth = ensureLineMetrics(line).width;
      maxWidth = Math.max(maxWidth, lineWidth);
      const top = lineIndex * rowHeight;
      const selectionRects = [];
      const matchRects = [];
      const carets = [];

      for (const range of ranges) {
        const start = Math.max(range.start, lineStart);
        const end = Math.min(range.end, lineStart + line.length);
        if (start < end) {
          const left = offsetToX(line, start - lineStart);
          selectionRects.push({ left, width: Math.max(1, offsetToX(line, end - lineStart) - left) });
        }
        if (range.start === range.end && range.start >= lineStart && range.start <= lineStart + line.length) {
          carets.push({ left: offsetToX(line, range.start - lineStart) });
        }
      }

      for (let index = 0; index < matches.length; index += 1) {
        const match = matches[index];
        const start = Math.max(match.start, lineStart);
        const end = Math.min(match.end, lineStart + line.length);
        if (start < end) {
          const left = offsetToX(line, start - lineStart);
          matchRects.push({ left, width: Math.max(1, offsetToX(line, end - lineStart) - left), current: index === activeMatchIndex });
        }
      }

      rows.push(`
        <div class="line-row" style="top:${top}px; height:${rowHeight}px;">
          ${matchRects.map((rect) => `<div class="match-rect${rect.current ? ' current-match' : ''}" style="left:${rect.left}px; width:${rect.width}px;"></div>`).join('')}
          ${selectionRects.map((rect) => `<div class="selection-rect" style="left:${rect.left}px; width:${rect.width}px;"></div>`).join('')}
          ${carets.map((rect) => `<div class="cursor-rect" style="left:${rect.left}px;"></div>`).join('')}
          <span class="line-text">${escapeHtml(line)}</span>
        </div>
      `);
      gutterRows.push(`<div class="gutter-row" style="top:${top}px; height:${rowHeight}px;"><span class="line-number">${lineIndex + 1}</span></div>`);
    }

    scrollContainer.innerHTML = `<div class="editor-content" style="height:${totalHeight}px; min-width:${maxWidth + 200}px;">${rows.join('')}</div>`;
    gutterContainer.innerHTML = `<div class="gutter-content" style="height:${totalHeight}px;">${gutterRows.join('')}</div>`;
    scrollContainer.scrollTop = scrollTop;
    scrollContainer.scrollLeft = scrollLeft;
  }

  function renderEditor() {
    if (!state.document) {
      return;
    }
    renderEditorSurface(editorScroll, lineGutter, {
      lines: state.lines,
      lineStarts: state.lineStarts,
      selectionRanges: state.selectionRanges,
      matches: state.matches,
      activeMatchIndex: state.activeMatchIndex,
    }, 'editor');
    renderStatus();
  }

  function renderPreview() {
    if (!state.preview) {
      return;
    }
    const lines = state.preview.content.split('\n');
    const lineStarts = [0];
    for (let index = 0; index < lines.length; index += 1) {
      lineStarts[index + 1] = lineStarts[index] + lines[index].length + (index < lines.length - 1 ? 1 : 0);
    }
    renderEditorSurface(previewScroll, previewGutter, {
      lines,
      lineStarts,
      selectionRanges: [],
      matches: [],
      activeMatchIndex: -1,
    }, 'preview');
  }

  function queueRender() {
    if (renderQueued) {
      return;
    }
    renderQueued = true;
    requestAnimationFrame(() => {
      renderQueued = false;
      renderEditor();
      if (state.preview) {
        renderPreview();
      }
    });
  }

  function scrollSelectionIntoView() {
    const info = lineInfoForOffset(getPrimaryRange().head);
    const caretX = offsetToX(info.line, info.columnOffset);
    const caretY = info.lineIndex * state.rowHeight;
    if (caretY < editorScroll.scrollTop + 16) {
      editorScroll.scrollTop = Math.max(0, caretY - state.rowHeight * 3);
    } else if (caretY + state.rowHeight > editorScroll.scrollTop + editorScroll.clientHeight - 16) {
      editorScroll.scrollTop = Math.max(0, caretY - editorScroll.clientHeight + state.rowHeight * 4);
    }
    if (caretX < editorScroll.scrollLeft + 24) {
      editorScroll.scrollLeft = Math.max(0, caretX - 40);
    } else if (caretX > editorScroll.scrollLeft + editorScroll.clientWidth - 24) {
      editorScroll.scrollLeft = Math.max(0, caretX - editorScroll.clientWidth + 80);
    }
  }

  function handleEditorMouseDown(event) {
    const rect = editorScroll.getBoundingClientRect();
    const x = editorScroll.scrollLeft + event.clientX - rect.left;
    const y = editorScroll.scrollTop + event.clientY - rect.top;
    const lineIndex = Math.max(0, Math.min(state.lines.length - 1, Math.floor(y / state.rowHeight)));
    const line = state.lines[lineIndex] || '';
    const offset = state.lineStarts[lineIndex] + xToOffset(line, Math.max(0, x));

    if (event.altKey || event.ctrlKey || event.metaKey) {
      state.selectionRanges = [...state.selectionRanges, { anchor: offset, head: offset }];
      finishGroup();
      queueRender();
      return;
    }

    if (event.detail >= 3) {
      state.selectionRanges = [{ anchor: state.lineStarts[lineIndex], head: state.lineStarts[lineIndex] + line.length }];
    } else if (event.detail === 2 && segmenterWord) {
      const relative = offset - state.lineStarts[lineIndex];
      const segments = Array.from(segmenterWord.segment(line));
      let selected = { start: 0, end: line.length };
      for (const segment of segments) {
        const end = segment.index + segment.segment.length;
        if (segment.isWordLike && segment.index <= relative && relative <= end) {
          selected = { start: segment.index, end };
          break;
        }
      }
      state.selectionRanges = [{ anchor: state.lineStarts[lineIndex] + selected.start, head: state.lineStarts[lineIndex] + selected.end }];
    } else {
      state.selectionRanges = [{ anchor: offset, head: offset }];
      dragSelection = { start: offset, active: true };
    }
    finishGroup();
    queueRender();
    scrollSelectionIntoView();
  }

  function handleEditorMouseMove(event) {
    if (!dragSelection || !dragSelection.active) {
      return;
    }
    const rect = editorScroll.getBoundingClientRect();
    const x = editorScroll.scrollLeft + event.clientX - rect.left;
    const y = editorScroll.scrollTop + event.clientY - rect.top;
    const lineIndex = Math.max(0, Math.min(state.lines.length - 1, Math.floor(y / state.rowHeight)));
    const line = state.lines[lineIndex] || '';
    const offset = state.lineStarts[lineIndex] + xToOffset(line, Math.max(0, x));
    state.selectionRanges = [{ anchor: dragSelection.start, head: offset }];
    queueRender();
    scrollSelectionIntoView();
  }

  function finishDragging() {
    dragSelection = null;
  }

  function handleEditorShortcut(event) {
    const isMac = navigator.platform.toLowerCase().includes('mac');
    const mod = isMac ? event.metaKey : event.ctrlKey;
    const key = event.key.toLowerCase();

    if (mod && key === 'f') {
      event.preventDefault();
      openFindBar();
      return true;
    }
    if (mod && key === 's') {
      event.preventDefault();
      saveReport();
      return true;
    }
    if (mod && key === 'z' && !event.shiftKey) {
      event.preventDefault();
      handleUndo();
      return true;
    }
    if (mod && (key === 'y' || (key === 'z' && event.shiftKey))) {
      event.preventDefault();
      handleRedo();
      return true;
    }
    if (mod && key === 'a') {
      event.preventDefault();
      selectAll();
      return true;
    }
    return false;
  }

  function handleEditorKeyDown(event) {
    if (handleEditorShortcut(event)) {
      return;
    }

    const mod = event.ctrlKey || event.metaKey;
    const shift = event.shiftKey;
    const key = event.key;

    if (key === 'Escape') {
      event.preventDefault();
      findInput.focus();
      return;
    }
    if (key === 'Tab') {
      event.preventDefault();
      insertTab(shift);
      return;
    }
    if (key === 'Enter') {
      event.preventDefault();
      typeText('\n');
      return;
    }
    if (key === 'Backspace') {
      event.preventDefault();
      deleteByDirection(-1);
      return;
    }
    if (key === 'Delete') {
      event.preventDefault();
      deleteByDirection(1);
      return;
    }
    if (key === 'ArrowLeft') {
      event.preventDefault();
      moveRanges(-1, { shift, byWord: mod });
      return;
    }
    if (key === 'ArrowRight') {
      event.preventDefault();
      moveRanges(1, { shift, byWord: mod });
      return;
    }
    if (key === 'ArrowUp') {
      event.preventDefault();
      moveVertical(-1, shift);
      return;
    }
    if (key === 'ArrowDown') {
      event.preventDefault();
      moveVertical(1, shift);
      return;
    }
    if (key === 'Home') {
      event.preventDefault();
      state.selectionRanges = state.selectionRanges.map((range) => {
        const info = lineInfoForOffset(range.head);
        const target = mod ? 0 : info.lineStart;
        return shift ? { anchor: range.anchor, head: target } : { anchor: target, head: target };
      });
      state.selectionRanges = dedupeCollapsed(sortRanges(state.selectionRanges));
      finishGroup();
      queueRender();
      scrollSelectionIntoView();
      return;
    }
    if (key === 'End') {
      event.preventDefault();
      state.selectionRanges = state.selectionRanges.map((range) => {
        const info = lineInfoForOffset(range.head);
        const target = mod ? state.content.length : info.lineStart + info.line.length;
        return shift ? { anchor: range.anchor, head: target } : { anchor: target, head: target };
      });
      state.selectionRanges = dedupeCollapsed(sortRanges(state.selectionRanges));
      finishGroup();
      queueRender();
      scrollSelectionIntoView();
      return;
    }
    if (mod && key === 'g') {
      event.preventDefault();
      navigateMatches(shift ? -1 : 1);
      return;
    }
    if (key.length === 1 && !mod) {
      event.preventDefault();
      typeText(key);
    }
  }

  function handlePaste(event) {
    event.preventDefault();
    typeText(event.clipboardData?.getData('text/plain') || '');
  }

  function handleCopy(event) {
    const range = getPrimaryRange();
    if (range.start === range.end) {
      return;
    }
    event.preventDefault();
    event.clipboardData?.setData('text/plain', state.content.slice(range.start, range.end));
  }

  function handleCut(event) {
    const range = getPrimaryRange();
    if (range.start === range.end) {
      return;
    }
    event.preventDefault();
    event.clipboardData?.setData('text/plain', state.content.slice(range.start, range.end));
    applyReplacement([range], '', 'cut');
  }

  function handleFindInputKeyDown(event) {
    if (event.key === 'Escape') {
      event.preventDefault();
      editorScroll.focus();
      return;
    }
    if (event.key === 'Enter') {
      event.preventDefault();
      navigateMatches(event.shiftKey ? -1 : 1);
    }
  }

  function handleScroll() {
    queueRender();
  }

  function handlePreviewScroll() {
    previewScrollState = { top: previewScroll.scrollTop, left: previewScroll.scrollLeft };
    queueRender();
  }

  function handleWindowResize() {
    metricsCache.clear();
    queueRender();
  }

  function bindUi() {
    editorScroll.addEventListener('keydown', handleEditorKeyDown);
    editorScroll.addEventListener('paste', handlePaste);
    editorScroll.addEventListener('copy', handleCopy);
    editorScroll.addEventListener('cut', handleCut);
    editorScroll.addEventListener('mousedown', handleEditorMouseDown);
    editorScroll.addEventListener('mousemove', handleEditorMouseMove);
    window.addEventListener('mouseup', finishDragging);
    editorScroll.addEventListener('scroll', handleScroll);
    previewScroll.addEventListener('scroll', handlePreviewScroll);
    findInput.addEventListener('input', () => {
      state.findQuery = findInput.value;
      state.activeMatchIndex = 0;
      findMatches();
    });
    findInput.addEventListener('keydown', handleFindInputKeyDown);
    replaceInput.addEventListener('keydown', (event) => {
      if (event.key === 'Escape') {
        editorScroll.focus();
      }
    });
    findToggleButton.addEventListener('click', () => {
      findBar.hidden = !findBar.hidden;
      if (!findBar.hidden) {
        findInput.focus();
        findInput.select();
      } else {
        editorScroll.focus();
      }
    });
    findPrevButton.addEventListener('click', () => navigateMatches(-1));
    findNextButton.addEventListener('click', () => navigateMatches(1));
    replaceCurrentButton.addEventListener('click', replaceCurrentMatch);
    replaceAllButton.addEventListener('click', replaceAllMatches);
    saveButton.addEventListener('click', saveReport);
    reloadButton.addEventListener('click', reloadLatest);
    discardButton.addEventListener('click', reloadLatest);
    undoButton.addEventListener('click', handleUndo);
    redoButton.addEventListener('click', handleRedo);
    closePreviewButton.addEventListener('click', closePreview);
    previewModal.addEventListener('click', (event) => {
